/* ---- the inline <script> of index.html, verbatim. Guarded by the body class: Instatic has
   one script asset for every page (trap 17), and this code throws on a page without its elements. ---- */
if (document.body.classList.contains('pg-home')) {
    document.querySelectorAll('.faq-q').forEach(btn=>btn.addEventListener('click',()=>btn.parentElement.classList.toggle('open')));
    document.getElementById('leadForm').addEventListener('submit',function(e){e.preventDefault();document.getElementById('success').style.display='block';});
}

/* ---- the inline <script> of survey/index.html, verbatim. Guarded by the body class: Instatic has
   one script asset for every page (trap 17), and this code throws on a page without its elements. ---- */
if (document.body.classList.contains('pg-survey')) {
    (()=>{
      const form=document.getElementById('growthSurvey');
      const steps=[...form.querySelectorAll('.step')];
      const prev=document.getElementById('prevButton');
      const next=document.getElementById('nextButton');
      const submit=document.getElementById('submitButton');
      const bar=document.getElementById('progressBar');
      const stepText=document.getElementById('stepText');
      const progressText=document.getElementById('progressText');
      const satisfaction=document.getElementById('marketing_satisfaction');
      const satisfactionValue=document.getElementById('satisfactionValue');
      const storageKey='brandklout-bk21-survey';
      let current=0;

      function updateView(focus=true){
        steps.forEach((step,index)=>step.classList.toggle('active',index===current));
        const percent=Math.round(((current+1)/steps.length)*100);
        bar.style.width=percent+'%';
        stepText.textContent=`Step ${current+1} of ${steps.length}`;
        progressText.textContent=`${percent}% complete`;
        prev.hidden=current===0;
        next.hidden=current===steps.length-1;
        submit.hidden=current!==steps.length-1;
        if(focus){steps[current].querySelector('h2').setAttribute('tabindex','-1');steps[current].querySelector('h2').focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});}
      }

      function validateStep(step){
        let valid=true;
        const firstInvalid=[...step.querySelectorAll('input,select,textarea')].find(field=>field.required&&!field.checkValidity());
        if(firstInvalid){firstInvalid.reportValidity();valid=false;}
        step.querySelectorAll('.choice-group[data-required="true"]').forEach(group=>{
          const checked=group.querySelector('input:checked');
          group.classList.toggle('invalid',!checked);
          if(!checked)valid=false;
        });
        return valid;
      }

      function collectAnswers(){
        const answers={};
        new FormData(form).forEach((value,key)=>{
          if(key==='form-name'||key==='bot-field')return;
          if(Object.prototype.hasOwnProperty.call(answers,key))answers[key]=[].concat(answers[key],value);else answers[key]=value;
        });
        return answers;
      }

      function saveAnswers(){try{localStorage.setItem(storageKey,JSON.stringify(collectAnswers()));}catch(error){}}
      function restoreAnswers(){
        try{
          const answers=JSON.parse(localStorage.getItem(storageKey)||'{}');
          Object.entries(answers).forEach(([name,value])=>setAnswer(name,value));
        }catch(error){}
      }
      function setAnswer(name,value){
        const fields=[...form.elements].filter(field=>field.name===name);
        if(!fields.length)return false;
        const values=Array.isArray(value)?value:String(value).split(',').map(item=>item.trim());
        fields.forEach(field=>{
          if(field.type==='checkbox'||field.type==='radio')field.checked=values.includes(field.value);
          else field.value=Array.isArray(value)?value[0]:value;
          field.dispatchEvent(new Event('change',{bubbles:true}));
        });
        return true;
      }

      next.addEventListener('click',()=>{if(validateStep(steps[current])){saveAnswers();current+=1;updateView();}});
      prev.addEventListener('click',()=>{current=Math.max(0,current-1);updateView();});
      form.addEventListener('input',saveAnswers);
      form.addEventListener('change',event=>{event.target.closest('.choice-group')?.classList.remove('invalid');saveAnswers();});
      satisfaction.addEventListener('input',()=>satisfactionValue.textContent=satisfaction.value);
      form.addEventListener('submit',event=>{
        for(let index=0;index<steps.length;index+=1){if(!validateStep(steps[index])){event.preventDefault();current=index;updateView();return;}}
        try{localStorage.removeItem(storageKey);}catch(error){}
      });

      if(new URLSearchParams(location.search).get('submitted')==='true'){
        form.hidden=true;document.querySelectorAll('.progress-meta,.progress-track').forEach(el=>el.hidden=true);document.getElementById('successPanel').classList.add('show');
      }else{restoreAnswers();satisfactionValue.textContent=satisfaction.value;updateView(false);}

      const context=document.modelContext;
      if(context?.registerTool){
        const lifecycle=new AbortController();
        try{
          Promise.resolve(context.registerTool({name:'stage_growth_survey_answers',title:'Stage growth survey answers',description:'Fill visible BrandKlout growth survey fields without submitting the form. Multiple-choice values may be supplied as comma-separated text.',inputSchema:{type:'object',properties:{answers:{type:'object',additionalProperties:{type:'string'}},step:{type:'integer',minimum:1,maximum:4}},required:['answers'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.answers!=='object'||Array.isArray(input.answers))throw new Error('answers must be an object');const filled=[];for(const [name,value] of Object.entries(input.answers)){if(typeof value!=='string')throw new Error(`Answer for ${name} must be text`);if(setAnswer(name,value))filled.push(name);}if(Number.isInteger(input.step)){current=input.step-1;updateView(false);}saveAnswers();return{filled,currentStep:current+1,submitted:false};}},{signal:lifecycle.signal})).catch(()=>{});
        }catch(error){}
      }
    })();
}
